    ok: true,
    cost,
    skillKey: raisesSkill ? skillKey : null,
    skillLevel: raisesSkill ? currentSkillLevel + 1 : null,
    raisesSkill,
    keptSkillPoints,
    gainedPoints,
    finalBreakthrough: isFinal,
    psycheCost,
    psycheHave,
