const buildMasuDonation = ({
  masuMons,
  targetId,
  gold,
  monsterRosterIds,
  draftMonsterRoster,
  unlockedMonsterIds,
  validBaseIds,
  requiredCount,
  lockedIds = []
}) => {
  const donated = masuMons.find(m => String(m.id) === String(targetId));
  if (!donated) return {
    ok: false,
    reason: '対象のマスモンはすでに所持していません。'
  };
  if (isMasuLocked(lockedIds, targetId)) return {
    ok: false,
    reason: `「${donated.name}」はお気に入り(🔒)なので寄付できません。お気に入りを外してから寄付してください。`
  };
  const nextMasuMons = masuMons.filter(m => String(m.id) !== String(targetId));
  const active = repairRosterAfterDonation(monsterRosterIds, donated, nextMasuMons, unlockedMonsterIds, validBaseIds, requiredCount);
  if (!active.ok) return active;
  const draft = repairRosterAfterDonation(draftMonsterRoster, donated, nextMasuMons, unlockedMonsterIds, validBaseIds, requiredCount);
  if (!draft.ok) return draft;
  const diamonds = donationDiamondValue(donated.bondXp);
  const psyche = donationPsycheValue(donated);
  return {
    ok: true,
    donated,
    diamonds,
    psyche,
    nextGold: donationDiamondValue(gold) + diamonds,
    nextMasuMons,
    nextRoster: active.roster,
    nextDraftRoster: draft.roster
  };
};
const buildMasuDonations = ({
  targetIds,
  ...state
}) => {
  const ids = [...new Set((Array.isArray(targetIds) ? targetIds : []).map(String))];
  if (!ids.length) return {
    ok: false,
    reason: '寄付するマスモンを選んでください。'
  };
  let current = {
    ...state
  };
  const donated = [];
  let diamonds = 0,
    psyche = 0;
  for (const targetId of ids) {
    const result = buildMasuDonation({
      ...current,
      targetId
    });
    if (!result.ok) return result;
    donated.push(result.donated);
    diamonds += result.diamonds;
    psyche += result.psyche;
    current = {
      ...current,
      masuMons: result.nextMasuMons,
      gold: result.nextGold,
      monsterRosterIds: result.nextRoster,
      draftMonsterRoster: result.nextDraftRoster
    };
  }
  return {
    ok: true,
    donated,
    diamonds,
    psyche,
    nextGold: current.gold,
    nextMasuMons: current.masuMons,
    nextRoster: current.monsterRosterIds,
    nextDraftRoster: current.draftMonsterRoster
  };
};
