const enemyActionNoticeLabel = def => def && (def.noticeLabel || def.category) || '';
const ENEMY_ACTION_ICONS = {
  ATTACK: '👊',
  CHARGE: '✨',
  SPECIAL: '🔥',
  WAIT: '⏳',
  MOVE: '🏃',
  ROAR: '📢',
  REGEN: '💚',
  PIERCE_CHARGE: '⚔️'
};
const TACTICS_VARIANT_ICONS = {
  sweep: '🌪️',
  rush: '💥',
  pierce: '🗡️',
  allout: '🌊'
};
const chooseEnemyAction = (ent, currentDist, random = Math.random, state = {}) => {
  const actions = enemyActionProbabilities(ent, currentDist, state),
    roll = random(),
    available = actions.filter(a => a.available);
  let cursor = roll;
  const selected = available.find(a => {
    cursor -= a.probability;
    return cursor < 0;
  }) || available[available.length - 1];
  if (!selected) return null;
  if (selected.type === 'MOVE') {
    const targets = RANGE_LABELS.map((_, i) => i).filter(i => i !== currentDist);
    const targetDist = targets[Math.min(targets.length - 1, Math.floor(random() * targets.length))];
    return {
      type: selected.type,
      value: 0,
      label: `移動: ${RANGE_LABELS[targetDist]}`,
      targetDist,
      icon: ENEMY_ACTION_ICONS.MOVE,
      notice: enemyActionNoticeLabel(selected),
      category: selected.category,
      actionId: selected.id
    };
  }
  if (selected.variant === 'sweep') {
    return {
      type: selected.type,
      variant: selected.variant,
      sweepDist: currentDist,
      value: Math.floor(ent.atk * selected.multiplier),
      missValue: Math.floor(ent.atk * (selected.missMultiplier ?? 1)),
      label: `${enemyActionDisplayName(ent, selected)}: ${RANGE_LABELS[currentDist]}`,
      icon: TACTICS_VARIANT_ICONS.sweep,
      notice: enemyActionNoticeLabel(selected),
      category: selected.category,
      actionId: selected.id
    };
  }
  if (selected.variant) {
    return {
      type: selected.type,
      variant: selected.variant,
      hits: Math.max(1, Math.floor(Number(selected.hits) || 1)),
      ...(selected.targetsAll ? {
        targetsAll: true
      } : {}),
      value: Math.floor(ent.atk * selected.multiplier),
      label: enemyActionDisplayName(ent, selected),
      icon: TACTICS_VARIANT_ICONS[selected.variant] || ENEMY_ACTION_ICONS[selected.type] || '⏳',
      notice: enemyActionNoticeLabel(selected),
      category: selected.category,
      actionId: selected.id
    };
  }
  return {
    type: selected.type,
    ...(selected.targetsAll ? {
      targetsAll: true
    } : {}),
    value: Math.floor(ent.atk * selected.multiplier),
    label: enemyActionDisplayName(ent, selected),
    icon: ENEMY_ACTION_ICONS[selected.type] || '⏳',
    notice: enemyActionNoticeLabel(selected),
    category: selected.category,
    actionId: selected.id
  };
};
