const ensureTacticsExUniqueInHand = ({
  hand,
  deck,
  graveyard
}, predicate, handMax = 5, keep = null) => {
  const h = Array.isArray(hand) ? hand.slice() : [],
    d = Array.isArray(deck) ? deck.slice() : [],
    g = Array.isArray(graveyard) ? graveyard.slice() : [];
  if (h.some(predicate)) return {
    hand: h,
    deck: d,
    graveyard: g,
    moved: false
  };
  let card = null;
  let at = d.findIndex(predicate);
  if (at >= 0) card = d.splice(at, 1)[0];else {
    at = g.findIndex(predicate);
    if (at >= 0) card = g.splice(at, 1)[0];
  }
  if (!card) return {
    hand: h,
    deck: d,
    graveyard: g,
    moved: false
  };
  if (h.length >= handMax) {
    let out = h.length - 1;
    while (out >= 0 && typeof keep === 'function' && keep(h[out], out)) out -= 1;
    if (out < 0) return {
      hand: hand.slice(),
      deck: deck.slice(),
      graveyard: graveyard.slice(),
      moved: false
    };
    d.push(h[out]);
    h[out] = card;
    return {
      hand: h,
      deck: d,
      graveyard: g,
      moved: true
    };
  }
  h.push(card);
  return {
    hand: h,
    deck: d,
    graveyard: g,
    moved: true
  };
};
