const rhythmAssistSessionCheer = (assistantId, {
  level = 1,
  fc = false,
  marvRate = 0,
  ratio = 0,
  cleared = true,
  firstSong = false,
  diffId = ''
} = {}) => {
  if (level < RHYTHM_ASSIST_SESSION_CHEER_LEVEL || !cleared) return null;
  const hard = RHYTHM_BUDDY_DIFF_IDS.indexOf(diffId) >= RHYTHM_BUDDY_DIFF_IDS.indexOf('HARD');
  switch (assistantId) {
    case 'mua':
      return fc ? {
        exp: 0,
        points: 3,
        label: 'フルコンの応援 ビートP+3'
      } : null;
    case 'kiki':
      return marvRate >= 0.9 ? {
        exp: 0.1,
        points: 0,
        label: '正確さの応援 経験値+10%'
      } : null;
    case 'momosuke':
      return ratio >= 0.9 ? {
        exp: 0,
        points: 3,
        label: 'ライブの応援 ビートP+3'
      } : null;
    case 'dra':
      return {
        exp: 0.1,
        points: 0,
        label: 'ねばりの応援 経験値+10%'
      };
    case 'atsu':
      return ratio >= 0.95 ? {
        exp: 0,
        points: 3,
        label: '締めの応援 ビートP+3'
      } : null;
    case 'kyuko':
      return firstSong ? {
        exp: 0.2,
        points: 0,
        label: 'はじめての曲の応援 経験値+20%'
      } : null;
    case 'sorashido':
      return hard ? {
        exp: 0.1,
        points: 0,
        label: '計算の応援 経験値+10%'
      } : null;
    case 'erubin':
      return ratio < 0.7 ? {
        exp: 0,
        points: 3,
        label: '気づかいの応援 ビートP+3'
      } : null;
    default:
      return null;
  }
};
