function msxFxEnsureCss() {
  if (msxFxCssDone || typeof document === 'undefined') return;
  try {
    if (!document.getElementById('msxfx-css')) {
      const el = document.createElement('style');
      el.id = 'msxfx-css';
      el.textContent = MSXFX_CSS;
      document.head.appendChild(el);
    }
    msxFxCssDone = true;
  } catch (_) {}
}
