  if (tries <= 2) return `技を ${tries}回しか 撃てなかった`;
  if (hits / tries < 0.45) return `技が ${tries}回中 ${hits}回しか 当たらなかった`;
  const top = Object.entries(foe).sort((a, b) => b[1] - a[1])[0];
