  const rand = assistantLifeRng(`${salt}|friend|${abs}|${cand.join(',')}`);
  const social = cand.reduce((t, id) => t + (ASSISTANT_LIFE_PREFS[id] && ASSISTANT_LIFE_PREFS[id].social || 0.5), 0) / cand.length;
